<?php

class WorkforceModule
{
    public static function repair(PDO $pdo): void
    {
        if(Database::tableExists('users')){
            if(!Database::columnExists('users','employee_no'))$pdo->exec('ALTER TABLE users ADD employee_no VARCHAR(50) NULL');
            if(!Database::columnExists('users','mobile'))$pdo->exec('ALTER TABLE users ADD mobile VARCHAR(30) NULL');
            if(!Database::columnExists('users','force_password_change'))$pdo->exec('ALTER TABLE users ADD force_password_change TINYINT(1) NOT NULL DEFAULT 0');
            $index=$pdo->prepare('SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME="users" AND INDEX_NAME="uq_users_employee_no"');$index->execute();
            if((int)$index->fetchColumn()===0){$duplicate=$pdo->query('SELECT employee_no FROM users WHERE employee_no IS NOT NULL AND employee_no<>"" GROUP BY employee_no HAVING COUNT(*)>1 LIMIT 1')->fetchColumn();if($duplicate===false){try{$pdo->exec('ALTER TABLE users ADD UNIQUE KEY uq_users_employee_no(employee_no)');}catch(Throwable $e){error_log('employee_no unique index: '.$e->getMessage());}}}
        }
        $e=' ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci';
        $schema=[
