            "CREATE TABLE IF NOT EXISTS user_import_rows(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,batch_id BIGINT UNSIGNED NOT NULL,source_row INT UNSIGNED NOT NULL,employee_no VARCHAR(50) NULL,raw_data_json LONGTEXT NOT NULL,status ENUM('valid','error','created','updated','skipped') NOT NULL DEFAULT 'valid',error_message TEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_user_import_rows_batch(batch_id,status),CONSTRAINT fk_user_import_rows_batch FOREIGN KEY(batch_id) REFERENCES user_import_batches(id) ON DELETE CASCADE){$e}",
            "CREATE TABLE IF NOT EXISTS docs_categories(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(190) NOT NULL,slug VARCHAR(190) NOT NULL UNIQUE,parent_id INT UNSIGNED NULL,sort_order INT NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_docs_categories_parent(parent_id),CONSTRAINT fk_docs_categories_parent FOREIGN KEY(parent_id) REFERENCES docs_categories(id) ON DELETE SET NULL){$e}",
            "CREATE TABLE IF NOT EXISTS docs_articles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id INT UNSIGNED NULL,title VARCHAR(255) NOT NULL,slug VARCHAR(255) NOT NULL UNIQUE,summary TEXT NULL,content LONGTEXT NOT NULL,cover_image VARCHAR(500) NULL,attachment_path VARCHAR(500) NULL,attachment_name VARCHAR(255) NULL,attachment_mime VARCHAR(190) NULL,visibility_scope ENUM('all','units','roles','users') NOT NULL DEFAULT 'all',allowed_roles_json LONGTEXT NULL,allowed_units_json LONGTEXT NULL,allowed_users_json LONGTEXT NULL,require_read_confirmation TINYINT(1) NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1,created_by INT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_docs_articles_category(category_id),INDEX idx_docs_articles_active(active),CONSTRAINT fk_docs_articles_category FOREIGN KEY(category_id) REFERENCES docs_categories(id) ON DELETE SET NULL,CONSTRAINT fk_docs_articles_user FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL){$e}",
            "CREATE TABLE IF NOT EXISTS docs_read_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,doc_id BIGINT UNSIGNED NOT NULL,user_id INT UNSIGNED NOT NULL,read_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,confirmed_at DATETIME NULL,ip_address VARCHAR(45) NULL,user_agent VARCHAR(255) NULL,UNIQUE KEY uq_docs_read_user(doc_id,user_id),INDEX idx_docs_read_logs_doc(doc_id),CONSTRAINT fk_docs_read_logs_doc FOREIGN KEY(doc_id) REFERENCES docs_articles(id) ON DELETE CASCADE,CONSTRAINT fk_docs_read_logs_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE){$e}",
