            "CREATE TABLE IF NOT EXISTS payroll_import_rows(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,batch_id BIGINT UNSIGNED NOT NULL,source_row INT UNSIGNED NOT NULL,employee_no VARCHAR(50) NULL,raw_data_json LONGTEXT NOT NULL,status ENUM('valid','error','committed','skipped') NOT NULL DEFAULT 'valid',error_message TEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_payroll_rows_batch(batch_id,status),CONSTRAINT fk_payroll_rows_batch FOREIGN KEY(batch_id) REFERENCES payroll_import_batches(id) ON DELETE CASCADE){$e}",
