            "CREATE TABLE IF NOT EXISTS payroll_exports(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,slip_id BIGINT UNSIGNED NULL,period_id INT UNSIGNED NULL,export_type ENUM('pdf','image','zip','group_pdf') NOT NULL,file_path VARCHAR(500) NULL,generated_by INT UNSIGNED NULL,generated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_payroll_exports_slip(slip_id),CONSTRAINT fk_payroll_exports_slip FOREIGN KEY(slip_id) REFERENCES payroll_slips(id) ON DELETE CASCADE,CONSTRAINT fk_payroll_exports_period FOREIGN KEY(period_id) REFERENCES payroll_periods(id) ON DELETE CASCADE,CONSTRAINT fk_payroll_exports_user FOREIGN KEY(generated_by) REFERENCES users(id) ON DELETE SET NULL){$e}",
        ];foreach($schema as $sql)$pdo->exec($sql);
        $modules=[['docs.manage','مدیریت مستندات آموزشی'],['docs.view','مشاهده مستندات آموزشی'],['users.import_export','ایمپورت و اکسپورت کاربران'],['payroll.manage','مدیریت حقوق و دستمزد'],['payroll.import','ایمپورت حقوق و دستمزد'],['payroll.publish','انتشار و قفل فیش حقوقی'],['payroll.view_all','مشاهده همه فیش‌های حقوقی'],['payroll.own','مشاهده فیش حقوقی شخصی']];$stmt=$pdo->prepare("INSERT INTO modules(module_key,module_title,sort_order,status,created_at) VALUES(?,?,75,'active',NOW()) ON DUPLICATE KEY UPDATE module_title=VALUES(module_title)");foreach($modules as $module)$stmt->execute($module);
        $fields=[['employee_no','شماره پرسنلی','info','text','system',10],['full_name','نام و نام خانوادگی','info','text','system',20],['national_id','کد ملی','info','text','manual',30],['bank_account','شماره حساب','info','text','manual',40],['job_title','عنوان شغلی','info','text','system',50],['department','واحد سازمانی','info','text','system',60],['base_salary','حقوق پایه','earning','money','manual',100],['housing_allowance','حق مسکن','earning','money','manual',110],['food_allowance','بن کارگری','earning','money','manual',120],['overtime','اضافه‌کاری','earning','money','manual',130],['bonus','پاداش','earning','money','manual',140],['insurance','بیمه','deduction','money','manual',200],['tax','مالیات','deduction','money','manual',210],['loan','وام','deduction','money','manual',220],['advance','مساعده','deduction','money','manual',230],['total_earnings','جمع مزایا','calculated','money','system',900],['total_deductions','جمع کسورات','calculated','money','system',910],['net_pay','خالص پرداختی','calculated','money','system',920]];$f=$pdo->prepare('INSERT IGNORE INTO payroll_fields(field_key,label,field_type,data_type,calculation_type,sort_order,active,created_at,updated_at) VALUES(?,?,?,?,?,?,1,NOW(),NOW())');foreach($fields as $row)$f->execute($row);
